example.before:
def read_header(path):
    fd = os.open(path, os.O_RDONLY)
    return os.read(fd, 16)    # fd is never closed

example.after:
def read_header(path):
    with open(path, "rb") as f:   # closed even on error
        return f.read(16)
# watch it: ls /proc/PID/fd | wc -l  (should stay flat)

